const assert = require('node:assert/strict');
const p = require('../../答題紀錄與隨機練習.js');
const questions = Array.from({length:20}, (_,i) => ({p:62,s:i < 10 ? 1 : 2,n:i+1,a:'2'}));
const answers = new Map(questions.slice(0,16).map(q => [p.key(q),2]));
let result = p.score(questions, answers);
assert.equal(result.score,80);
assert.equal(result.accuracy,100);
assert.equal(result.unanswered,4);
assert.equal(result.subjects[0].score,100);
assert.equal(result.subjects[1].score,60);
answers.set(p.key(questions[0]),1);
const peeked = new Set([p.key(questions[1])]);
result = p.score(questions, answers, peeked);
assert.equal(result.score,70);
assert.equal(result.wrong,1);
assert.equal(result.assisted,1);
assert.equal(result.correct+result.wrong+result.assisted+result.unanswered,20);
assert.equal(p.score([],new Map()).score,0);
assert.equal(p.score(questions,new Map()).accuracy,null);
assert.equal(p.score(questions.slice(0,3),new Map([[p.key(questions[0]),2]])).score,33.3);
const data = {};
const storage = {getItem:k=>data[k]??null,setItem:(k,v)=>{data[k]=v;}};
const a = p.loadHistory(storage), b = p.loadHistory(storage);
const entry = {...result,label:'第62期・信託法規',mode:'exam',date:new Date().toISOString(),seconds:65};
p.addHistory(storage,a,entry);
p.addHistory(storage,b,{...entry,score:95});
assert.equal(p.loadHistory(storage).entries.length,2,'Concurrent pages preserve both saved results');
for(let i=0;i<25;i++)p.addHistory(storage,a,entry);
assert.equal(p.loadHistory(storage).entries.length,20);
data.trust_exam_scores_v1='{bad';
p.addHistory(storage,a,entry);
assert.equal(data.trust_exam_scores_v1,'{bad');
assert.equal(a.writable,false);
assert(a.message);
const quota = {getItem:()=>null,setItem:()=>{throw Error('quota');}};
const state = p.loadHistory(quota);
p.addHistory(quota,state,entry);
p.addHistory(quota,state,entry);
assert.equal(state.entries.length,2);
assert.equal(state.writable,false);
const invalid = {getItem:()=>JSON.stringify({version:1,entries:[{...entry,score:101}]})};
assert.equal(p.loadHistory(invalid).writable,false);
console.log('PASS: round scores, unanswered/assisted rules, subject scores, rounding and safe score history');
